/** {@link ChannelMeta.kind} value used by {@link gitlabChannel}. */
export const GITLAB_CHANNEL_KIND = "gitlab";
/**
 * GitLab `object_kind` values (the `X-Gitlab-Event` payload discriminator)
 * each authored hook subscribes to. `merge_request` is always declared: it
 * is the default dispatch when no `onMergeRequest` hook exists.
 */
const HOOK_EVENTS = [
    ["onMergeRequest", "merge_request"],
    ["onNote", "note"],
    ["onPush", "push"],
    ["onPipeline", "pipeline"],
    ["onTagPush", "tag_push"],
];
export function deriveGitLabWebhookEvents(options) {
    if (options.webhookEvents !== undefined) {
        return [...new Set(options.webhookEvents.map((event) => event.trim()).filter(Boolean))];
    }
    const events = ["merge_request"];
    for (const [hook, objectKind] of HOOK_EVENTS) {
        if (options[hook] !== undefined) {
            events.push(objectKind);
        }
    }
    return [...new Set(events)];
}
